import { getReducedMotionPreference } from "../motion";

/** Short, non-animated completion cue for reduced-motion users */
function celebrateMinimal(): void {
  try {
    const el = document.createElement("div");
    el.className = "celebrate-minimal";
    el.textContent = "Task completed";
    el.setAttribute("role", "status");
    el.setAttribute("aria-live", "polite");
    document.body.appendChild(el);
    requestAnimationFrame(() => {
      el.style.opacity = "1";
    });
    window.setTimeout(() => {
      el.style.opacity = "0";
      window.setTimeout(() => el.remove(), 220);
    }, 550);
  } catch {
    /* ignore */
  }
}

export function celebrate(selector: string = ".container") {
  if (getReducedMotionPreference()) {
    celebrateMinimal();
    return;
  }

  try {
    const host = (document.querySelector(selector) as HTMLElement) || document.body;
    const rect = host.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + 20;

    const layer = document.createElement("div");
    layer.className = "confetti-layer";
    document.body.appendChild(layer);

    const colors = ["#00e5ff", "#7c4dff", "#14f195", "#f59e0b", "#ef4444", "#22c55e"];

    const count = 20;
    for (let i = 0; i < count; i++) {
      const div = document.createElement("div");
      div.className = "confetti-piece";
      const angle = (Math.PI * 2 * i) / count + Math.random() * 0.6;
      const dist = 60 + Math.random() * 60;
      const dx = Math.cos(angle) * dist;
      const dy = Math.sin(angle) * dist - 60;
      div.style.left = `${cx}px`;
      div.style.top = `${cy}px`;
      (div.style as CSSStyleDeclaration & { "--dx": string; "--dy": string }).setProperty("--dx", `${dx}px`);
      (div.style as CSSStyleDeclaration & { "--dx": string; "--dy": string }).setProperty("--dy", `${dy}px`);
      div.style.background = colors[Math.floor(Math.random() * colors.length)];
      layer.appendChild(div);
    }

    window.setTimeout(() => {
      layer.remove();
    }, 1000);
  } catch {
    /* ignore */
  }
}
